// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address actor) public {
        // Owner is whoever deployed c in setUp (this test contract).
        // Restrict only enough to keep the domain admissible: a non-owner caller.
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        vm.prank(actor);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: any non-owner call to owned() must revert.
        assertTrue(!ok, "non-owner call to owned() must revert");
    }
}
